/* FUNCTION ************************************************************************************************************
 *
 * Function Name : BOARD_InitPins
 * Description   : 
 *
 * END ****************************************************************************************************************/
/* Function assigned for the Cortex-M33 */
void BOARD_InitPins(void)
{
    /* Initialize FC3_USART_DATA functionality on pin GPIO_24 (pin E5) */
    IO_MUX_SetPinMux(IO_MUX_FC3_USART_DATA);

    /* SD card (SPI mode): FC1 SCK/MISO/MOSI on GPIO7/8/9, CS as GPIO6 */
    IO_MUX_SetPinMux(IO_MUX_FC1_SPI_NO_SSEL);
    IO_MUX_SetPinMux(IO_MUX_GPIO6);
    /* CS and MISO pulled up (the card's DO is high-Z until it enters SPI mode); SCK/MOSI push-pull, no pull */
    IO_MUX_SetPinConfig(6U, IO_MUX_PinConfigPullUp);
    IO_MUX_SetPinConfig(7U, IO_MUX_PinConfigNoPull);
    IO_MUX_SetPinConfig(8U, IO_MUX_PinConfigPullUp);
    IO_MUX_SetPinConfig(9U, IO_MUX_PinConfigNoPull);
}
